import{_ as r,C as s,o as h,c as d,j as t,a as n,E as a,a6 as l}from"./chunks/framework.CCKCzdWs.js";const u="/screenshots/runner-settings.png",c="/screenshots/runner-runs.png",p="/screenshots/runner-run-results.png",R=JSON.parse('{"title":"Piwi Runner","description":"Piwi Runner takes Run on my machine requests from a team instance without the dashboard: where to get it, how it installs beside the desktop app, and how it stays in the tray.","frontmatter":{"title":"Piwi Runner","description":"Piwi Runner takes Run on my machine requests from a team instance without the dashboard: where to get it, how it installs beside the desktop app, and how it stays in the tray.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/piwi-runner.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/piwi-runner.html"}],["meta",{"property":"og:title","content":"Piwi Runner | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Piwi Runner takes Run on my machine requests from a team instance without the dashboard: where to get it, how it installs beside the desktop app, and how it stays in the tray."}]]},"headers":[],"relativePath":"features/piwi-runner.md","filePath":"features/piwi-runner.md","lastUpdated":1795462317000}'),w={name:"features/piwi-runner.md"};function g(m,e,f,k,y,b){const o=s("Needs"),i=s("DownloadApps");return h(),d("div",null,[e[0]||(e[0]=t("h1",{id:"piwi-runner",tabindex:"-1"},[n("Piwi Runner "),t("a",{class:"header-anchor",href:"#piwi-runner","aria-label":'Permalink to "Piwi Runner"'},"​")],-1)),a(o,{admin:""}),e[1]||(e[1]=t("p",null,[n("Piwi Runner takes "),t("a",{href:"./run-on-my-machine.html"},"Run on my machine"),n(" requests from one team instance, without the dashboard: one window for the connection, the confirmation of each request and the runs it started. It is for a machine that only runs what the instance asks, where the "),t("a",{href:"./desktop.html"},"desktop app"),n(" and its local dashboard are more than needed. It keeps no database and serves no dashboard.")],-1)),e[2]||(e[2]=t("h2",{id:"where-it-is",tabindex:"-1"},[n("Where it is "),t("a",{class:"header-anchor",href:"#where-it-is","aria-label":'Permalink to "Where it is"'},"​")],-1)),a(i,{app:"runner"}),e[3]||(e[3]=l('<p>Its installers are of the same kinds as the desktop app&#39;s, for the same systems, with the same needs and the same unsigned first start: <a href="./desktop.html#where-it-is">the desktop app&#39;s installers</a>.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Piwi Runner checks the latest release when it starts, and a notification says when a newer version is out. <strong>Check for updates…</strong> in the system tray menu checks again; when one is found, <strong>Install and restart</strong> downloads it, checks its signature, installs it the way it was installed (<code>.exe</code>, <code>.msi</code>, <code>.dmg</code>, <code>.AppImage</code>, <code>.deb</code> or <code>.rpm</code>) and starts the new version, after asking to stop the runs still going. Your connection and linked folders stay. <strong>Settings → About</strong> in its window shows the version installed and where the tray&#39;s update and log items are, with links to this page, the release notes and the page to report a problem. A new release&#39;s Piwi Runner files can reach the release a few minutes after the desktop app&#39;s; until then the check finds nothing new or fails, and the next one finds them. On a desktop that shows no tray icon, install a new version from the latest release over the old one.</p><h2 id="piwi-runner-or-the-desktop-app" tabindex="-1">Piwi Runner or the desktop app <a class="header-anchor" href="#piwi-runner-or-the-desktop-app" aria-label="Permalink to &quot;Piwi Runner or the desktop app&quot;">​</a></h2><p>You need one of the two, not both. The desktop app takes the same requests, with the same confirmation and checks, and adds the dashboard on your machine; a requested run can be paused, stepped and watched from either window. Piwi Runner is for a machine that only runs what the instance asks.</p><p>Installed together, they live side by side, and neither installer replaces the other: each has its own name, install folder, Linux package, settings, linked folders and keychain entry. Connected to the same instance, both are listed in <strong>Connected apps</strong>, and a request goes to the one you pick on the page.</p><h2 id="connect-it" tabindex="-1">Connect it <a class="header-anchor" href="#connect-it" aria-label="Permalink to &quot;Connect it&quot;">​</a></h2><p>Until it is connected, its window opens on the instance&#39;s address, with the three steps from a test there to its run here. It connects the way the desktop app does: enter the instance&#39;s address and click <strong>Connect</strong>, then allow <strong>Piwi Runner</strong> on the instance&#39;s page with the code the window shows. Its key stays in the operating system&#39;s keychain. Each project&#39;s folder is linked on the first request for it. The rest, from the confirmation to <strong>Stop</strong>, is described in <a href="./run-on-my-machine.html#in-the-app">Run on my machine</a>.</p><p>Once connected, the top of the window says which instance it takes requests from, with a dot of its state: green while connected, amber while it connects or the instance does not answer, when a line above the runs also says that its requests reach the machine again once it answers. A click on it opens the connection&#39;s settings.</p><p><strong>Settings</strong> shows a section at a time: <strong>Connection</strong> (the instance, a button that opens it in the browser, and <strong>Disconnect</strong>, which asks first: connecting again means allowing Piwi Runner on the instance again), <strong>Folders</strong> (the folder linked to each project, with <strong>Unlink</strong>: the next request for that project asks for its folder again), <strong>General</strong> (the two background settings and the language) and <strong>About</strong>.</p><figure><img src="'+u+'" alt="Piwi Runner&#39;s Settings on its Connection section: the instance it is connected to, Open piwi.example.com, Disconnect, and the list of sections: Connection, Folders, General and About"><figcaption>Settings, on the Connection section; the header says which instance Piwi Runner takes requests from.</figcaption></figure><h2 id="pause-and-watch-a-run" tabindex="-1">Pause and watch a run <a class="header-anchor" href="#pause-and-watch-a-run" aria-label="Permalink to &quot;Pause and watch a run&quot;">​</a></h2><p>Each run Piwi Runner starts shows in its window live, as the desktop app&#39;s runs show in its <a href="./desktop-runs.html">Local runs tray</a>: each worker&#39;s test and where it stands, <strong>Pause</strong>, <strong>Step</strong>, <strong>Resume</strong> and <strong>Finish</strong>, <strong>Pause all</strong> and <strong>Resume all</strong>, and the stopped test&#39;s page, live with <strong>Watch</strong>. A <code>page.pause()</code>, a step or a breakpoint waits in the window until you answer it, and the window comes to the front, on its runs. <a href="./watch-a-run.html#hold-failures"><strong>Hold failures</strong></a>, a switch on each running run you attend, off until you turn it on, keeps a failing test at its line too, until you resume it. Once the run reported to the instance, it shows <strong>Run #78 · Open</strong>, which opens its page there, and keeps it after the run ended. A run that goes on while the window reloads shows again, with <strong>Stop</strong>. <strong>Assert a region</strong> and <strong>Mock a request</strong> make their code in the window, to copy: Piwi Runner has no editor and writes no file. A requested run cannot be <a href="./share-live.html">shared live</a>: the instance gives it no <a href="./live-view.html">live view</a> key, since it <a href="./run-on-my-machine.html#a-requested-run-is-yours-alone">shows to you alone</a>. <strong>Inspect</strong> of a watched worker, which reads the test&#39;s pages from its trace, is the desktop app&#39;s alone.</p><p>The runs show as the desktop app&#39;s <a href="./local-runs-tray.html">Local runs</a> do: the list on the left, the run you pick on the right, and a select that names it in a narrow window. <strong>Running now</strong> lists the runs going on and <strong>Finished</strong> those that ended, the last to end first, each line saying how its run stands, whether a test of it waits at a stop, and how long it ran. A run you confirm shows at once, and a test that stops shows its run, unless you are working in the run shown. The run shown has its project, when it started and how long it has run, <strong>Stop</strong>, which gives way to <strong>Force stop</strong> while the run winds down, as in the <a href="./local-runs-tray.html#each-run">desktop app</a>, its workers live, the tests the request asked for and its output.</p><figure><img src="'+c+'" alt="Piwi Runner&#39;s runs: on the left, one run under Running now and two under Finished, one failed and one passed; on the right, the run going on, its worker running, with Pause, Watch, Hold failures and Stop"><figcaption>The run going on, shown beside the list, its worker live.</figcaption></figure><p>Once a run ended, its tests say how each came out, as its output tells it, a failed one with the first lines of its error, and it shows <strong>Run #78 · Open</strong> once it reported to the instance. The output keeps Playwright&#39;s colors and its last 2,000 lines, with a filter, <strong>Go to the first error</strong> and <strong>Copy output</strong>, as the <a href="./local-runs-tray.html#its-output">desktop app&#39;s</a> does. <strong>Clear finished</strong> empties the Finished list; the window keeps the last 15 runs that ended in any case, never dropping one the moment it ends.</p><figure><img src="'+p+'" alt="Piwi Runner&#39;s runs with the run that failed shown: its two tests, one passed and one failed with its error, and its output in Playwright&#39;s colors"><figcaption>The run that failed: how each test came out, and its output.</figcaption></figure><p>Piwi Runner is the hub of its own runs only: Piwi Picker, the editors and an agent reach the runs the desktop app or an editor starts, not Piwi Runner&#39;s.</p><h2 id="in-the-tray" tabindex="-1">In the tray <a class="header-anchor" href="#in-the-tray" aria-label="Permalink to &quot;In the tray&quot;">​</a></h2><p>Closing the window leaves Piwi Runner in the system tray, still connected, so the instance can reach it; a request brings the window forward. The tray menu has, with the <a href="./desktop.html">desktop app</a>&#39;s glyphs and in its order:</p><ul><li><strong>Open Piwi Runner</strong> (on Windows and macOS, a click on the icon does the same);</li><li><strong>Run in background</strong>, on by default: turned off, closing the window quits the app, once you agree to stop the runs still going;</li><li><strong>Start on login</strong>, which launches it in the tray when you sign in;</li><li><strong>Check for updates…</strong> and <strong>Show logs</strong>;</li><li><strong>Quit Piwi Runner</strong>, which stops its runs, after asking.</li></ul><p>The <strong>General</strong> section of the window&#39;s <strong>Settings</strong> has the same two settings, for a desktop that shows no tray icon (GNOME without an AppIndicator extension): turn <strong>Run in background</strong> off there, and closing the window quits.</p><p>Its icon is the Piwi mark on a teal tile with a play sign, so it reads apart from the desktop app&#39;s in the tray and the taskbar.</p><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><p>Piwi Runner speaks English, French, German, Spanish and Brazilian Portuguese, in its window, its tray menu and its questions: your system&#39;s language, or the one you choose in the <strong>General</strong> section of its window&#39;s <strong>Settings</strong>. German, Spanish and Portuguese are drafts no native reader has reviewed yet: while one is on screen, a line says so and links to a form for a correction. Test titles, files, commands and a run&#39;s output stay as they are, the reason a run could not start included, and so do two answers of the runs&#39; hub, where a locator picked on the image and a code made at a stop wait to be copied. The start screen keeps the language Runner started in until it starts again. The <a href="./desktop.html">desktop app</a> stays in English.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./run-on-my-machine.html">Run on my machine</a>: who may ask, how an administrator turns it on, and what a request holds</li><li><a href="./desktop.html">Desktop app</a>: the other app that takes requests, with a local dashboard</li></ul>',27))])}const q=r(w,[["render",g]]);export{R as __pageData,q as default};
